mapper.select:
SELECT *
FROM message_conversation
WHERE tenant_id = #{tenantId}
  AND conversation_type = 'CUSTOMER_SERVICE'
  AND customer_id = #{customerId}
  AND queue_code = #{queueCode}
  AND status = 'CLOSED'
  AND reopen_deadline >= #{now}
  AND del_flag = '0'
ORDER BY closed_time DESC
LIMIT 1

SELECT *
FROM message_conversation
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
FOR UPDATE

SELECT *
FROM message_conversation
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = '0'
LIMIT 1

SELECT 
FROM message_conversation c


WHERE c.tenant_id = #{tenantId}
  AND c.id = #{conversationId}
  AND c.del_flag = '0'

SELECT 
FROM message_conversation c


WHERE c.tenant_id = #{tenantId}
  AND c.del_flag = '0'






ORDER BY COALESCE(c.last_message_time, c.create_time) DESC, c.id DESC
LIMIT #{fetchSize}

SELECT c.id, c.conversation_type, c.queue_code, c.customer_id, c.assigned_staff_id, c.status, c.last_seq, c.last_message_summary, c.last_message_time, c.create_time, CASE WHEN c.status = 'WAITING' THEN c.create_time ELSE NULL END AS waiting_since, COALESCE(c.last_message_time, c.create_time) AS last_active_time, c.closed_time, c.reopen_deadline, c.context_payload, cp.participant_name AS customer_name, cp.participant_avatar AS customer_avatar, sp.participant_name AS assigned_staff_name, sp.participant_avatar AS assigned_staff_avatar, (SELECT pp.last_read_seq FROM message_participant pp WHERE pp.tenant_id = #{tenantId} AND pp.conversation_id = c.id AND pp.participant_type = 'MALL_USER' AND pp.participant_status = 'ACTIVE' AND pp.del_flag = '0' ORDER BY pp.joined_time DESC LIMIT 1) AS peer_last_read_seq FROM message_conversation c
WHERE c.tenant_id = #{tenantId} AND c.del_flag = '0'
ORDER BY COALESCE(c.last_message_time, c.create_time) DESC, c.id DESC LIMIT #{fetchSize}

SELECT COUNT(*)
FROM message_conversation c
INNER JOIN message_participant p ON p.tenant_id = #{tenantId}
    AND p.conversation_id = c.id
    AND p.participant_type = #{participantType}
    AND p.participant_id = #{participantId}
    AND p.participant_status = 'ACTIVE'
    AND p.del_flag = '0'
WHERE c.tenant_id = #{tenantId}
  AND c.del_flag = '0'
  AND c.status != 'CLOSED'
  AND c.last_seq > p.last_read_seq

SELECT *
FROM message_conversation
WHERE tenant_id = #{tenantId}
  AND conversation_type = 'CUSTOMER_SERVICE'
  AND status IN ('WAITING', 'ASSIGNED', 'ACTIVE')
  AND COALESCE(last_message_time, create_time) < #{inactiveBefore}
  AND del_flag = '0'
ORDER BY COALESCE(last_message_time, create_time) ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM message_conversation
WHERE tenant_id = #{tenantId}
  AND assigned_staff_id = #{staffId}
  AND status IN ('ASSIGNED', 'ACTIVE')
  AND del_flag = '0'
